<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f3f6fb;
        --panel: rgba(255, 255, 255, 0.92);
        --border: rgba(15, 23, 42, 0.08);
        --text: #0f172a;
        --muted: #475569;
        --accent: #4f46e5;
        --accent-strong: #4338ca;
        --accent-soft: rgba(79, 70, 229, 0.1);
        --shadow: 0 24px 60px rgba(15, 23, 42, 0.12);
        --radius: 24px;
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: flex;
        align-items: center;
        justify-content: center;
        padding: 32px 20px;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, rgba(79, 70, 229, 0.14), transparent 32%),
          linear-gradient(180deg, #f8fbff 0%, var(--bg) 100%);
        color: var(--text);
      }

      .app-shell {
        width: min(100%, 720px);
      }

      .card {
        background: var(--panel);
        backdrop-filter: blur(12px);
        border: 1px solid var(--border);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        padding: clamp(28px, 5vw, 40px);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        margin: 0 0 16px;
        padding: 8px 12px;
        border-radius: 999px;
        background: var(--accent-soft);
        color: var(--accent-strong);
        font-size: 0.85rem;
        font-weight: 700;
        letter-spacing: 0.01em;
      }

      h1 {
        margin: 0;
        font-size: clamp(2rem, 4vw, 2.8rem);
        line-height: 1.05;
      }

      .intro {
        margin: 14px 0 0;
        max-width: 56ch;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        margin-top: 28px;
      }

      .form-field {
        margin: 0;
      }

      fieldset {
        margin: 0;
        padding: 24px;
        border: 1px solid rgba(79, 70, 229, 0.14);
        border-radius: 20px;
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.95), rgba(244, 247, 255, 0.95));
      }

      legend {
        padding: 0 10px;
        font-size: 1.05rem;
        font-weight: 700;
        color: var(--text);
      }

      .helper-text {
        margin: 0 0 18px;
        color: var(--muted);
        font-size: 0.96rem;
      }

      .options {
        display: grid;
        gap: 14px;
      }

      .radio-option {
        display: flex;
        align-items: center;
        gap: 14px;
        padding: 16px 18px;
        border: 1px solid rgba(15, 23, 42, 0.08);
        border-radius: 16px;
        background: #fff;
        transition: border-color 160ms ease, box-shadow 160ms ease, transform 160ms ease;
        cursor: pointer;
      }

      .radio-option:hover {
        border-color: rgba(79, 70, 229, 0.28);
        box-shadow: 0 12px 30px rgba(79, 70, 229, 0.08);
        transform: translateY(-1px);
      }

      .radio-option:focus-within {
        border-color: var(--accent);
        box-shadow: 0 0 0 4px rgba(79, 70, 229, 0.14);
      }

      .radio-option input[type="radio"] {
        margin: 0;
        width: 20px;
        height: 20px;
        accent-color: var(--accent);
        flex: 0 0 auto;
      }

      .radio-copy {
        display: flex;
        flex-direction: column;
        gap: 4px;
      }

      .radio-title {
        font-size: 1rem;
        font-weight: 600;
      }

      .radio-description {
        color: var(--muted);
        font-size: 0.92rem;
      }

      .actions {
        margin-top: 24px;
      }

      .submit-button {
        appearance: none;
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        font: inherit;
        font-weight: 700;
        color: #fff;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        box-shadow: 0 14px 30px rgba(79, 70, 229, 0.28);
        cursor: pointer;
        transition: transform 160ms ease, box-shadow 160ms ease, filter 160ms ease;
      }

      .submit-button:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 34px rgba(79, 70, 229, 0.34);
        filter: brightness(1.02);
      }

      .submit-button:focus-visible {
        outline: 3px solid rgba(79, 70, 229, 0.25);
        outline-offset: 3px;
      }

      @media (max-width: 640px) {
        body {
          padding: 20px 16px;
        }

        fieldset {
          padding: 20px;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const options = [
        {
          id: "notify-email",
          value: "Email",
          description: "Receive updates in your inbox."
        },
        {
          id: "notify-sms",
          value: "SMS",
          description: "Get quick text message alerts."
        },
        {
          id: "notify-push",
          value: "Push Notifications",
          description: "See instant notifications on your device."
        }
      ];

      function renderApp() {
        const root = document.getElementById("root");
        root.innerHTML = App();
      }

      function App() {
        return AppShell({
          children: ProductCard({
            children: `
              <p class="eyebrow">Preferences</p>
              <h1>Choose your notification method</h1>
              <p class="intro">
                Tell us how you prefer to receive notifications so we can keep updates timely and relevant.
              </p>
              ${NotificationForm()}
            `
          })
        });
      }

      function AppShell(props) {
        return `
          <main class="app-shell">
            ${props.children}
          </main>
        `;
      }

      function ProductCard(props) {
        return `
          <section class="card" aria-labelledby="page-title">
            ${props.children.replace("<h1>", '<h1 id="page-title">')}
          </section>
        `;
      }

      function NotificationForm() {
        return `
          <form>
            <div class="form-field">
              <fieldset>
                <legend>How do you prefer to receive notifications?</legend>
                <p class="helper-text">Select one option before submitting your preference.</p>
                <div class="options" role="radiogroup" aria-label="Notification preference options">
                  ${options.map((option) => RadioOption(option)).join("")}
                </div>
              </fieldset>
            </div>
            <div class="actions">
              <button class="submit-button" type="submit">Submit</button>
            </div>
          </form>
        `;
      }

      function RadioOption(option) {
        return `
          <label class="radio-option" for="${option.id}">
            <input
              id="${option.id}"
              type="radio"
              name="notificationPreference"
              value="${option.value}"
              required
            />
            <span class="radio-copy">
              <span class="radio-title">${option.value}</span>
              <span class="radio-description">${option.description}</span>
            </span>
          </label>
        `;
      }

      renderApp();
    </script>
  </body>
</html>
